    content: "const fs=require('fs'),path=require('path');\nconst roots=['src/api/erp/finance','src/views/finance','src/store','src/utils'];\nconst terms=['启用','账套','activation','start_period','accounting_period','period_start','启用期间','当前账套','accountset','account_set'];\nfunction walk(p){\n if(!fs.existsSync(p)) return;\n for(const e of fs.readdirSync(p,{withFileTypes:true})){\n  const q=path.join(p,e.name);\n  if(e.isDirectory()){\n   if(['node_modules','.git','.turbo','dist'].includes(e.name)) continue;\n   walk(q);\n  } else {\n   let s=''; try{s=fs.readFileSync(q,'utf8')}catch{}\n   if(terms.some(t=>s.includes(t))) console.log(q);\n  }\n }\n}\nroots.forEach(walk);\n",
