    path: "apps/web-ele/tmp_hide_asset_balance_stamp_when_ok.cjs",
    content: "const fs = require('fs');\nconst path = require('path');\nconst file = path.join(process.cwd(), 'src/views/finance/assets/manage/index.vue');\nlet source = fs.readFileSync(file, 'utf8');\nconst target = `        <div\n          class=\"asset-balance-stamp\"`;\nconst replacement = `        <div\n          v-if=\"openingBalanceStatus !== '平衡'\"\n          class=\"asset-balance-stamp\"`;\nif (!source.includes(target)) {\n  console.error('missing asset balance stamp block');\n  process.exit(1);\n}\nsource = source.replace(target, replacement);\nfs.writeFileSync(file, source);\nconsole.log('hide asset balance stamp when balanced');\n",
