    path: "apps/web-ele/tmp_remove_asset_initialization_status_column.cjs",
    content: "const fs = require('fs');\nconst path = require('path');\nconst file = path.join(process.cwd(), 'src/views/finance/assets/manage/initialization/index.vue');\nlet source = fs.readFileSync(file, 'utf8');\nconst columnBlock = `          <ElTableColumn label=\"初始化状态\" width=\"120\">\n            <template #default=\"{ row }\">\n              <ElTag :type=\"isInitializationLocked(row) ? 'info' : 'success'\">\n                {{ isInitializationLocked(row) ? '已锁定' : '可维护' }}\n              </ElTag>\n            </template>\n          </ElTableColumn>\n`;\nif (!source.includes(columnBlock)) {\n  console.error('missing initialization status column block');\n  process.exit(1);\n}\nsource = source.replace(columnBlock, '');\nsource = source.replace(/\\n  ElTag,/, '');\nfs.writeFileSync(file, source);\nconsole.log('removed asset initialization status column');\n",
