    path: "tmp_cleanup_multi_column_toolbar_css.cjs",
    content: "const fs=require('fs');\nconst p='apps/web-ele/src/views/finance/ledger/multi-column/index.vue';\nlet s=fs.readFileSync(p,'utf8');\nconst blocks=[\n  /\\.period-badge \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-panel \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-panel--floating \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-panel__collapsed \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-panel__body \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-panel:hover \\.query-panel__body,[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-line \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-options-box \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-options-box__radios \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-options-box__radios :deep\\(\\.el-radio\\) \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-options-box__checkbox \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-label \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-buttons \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n  /\\.query-buttons :deep\\(\\.el-button\\) \\{[\\s\\S]*?\\n\\}\\n\\n/g,\n];\nfor(const re of blocks) s=s.replace(re,'');\nfs.writeFileSync(p,s);\n",
