    content: "const fs=require('fs');\nfor(const p of ['apps/web-ele/src/views/finance/funds/cashday/index.vue','apps/web-ele/src/views/finance/funds/bankjournal/index.vue']){\n const s=fs.readFileSync(p,'utf8');\n console.log('\\n--- '+p+' ---');\n for(const key of ['新增','删除','save','delete','onAdd','addRow','onDelete','deleteRow','saveCashdayRow','deleteCashdayRow','saveBankjournalRow','deleteBankjournalRow']){\n  const i=s.indexOf(key); if(i>=0) console.log('\\nKEY',key,'@',i,'\\n'+s.slice(Math.max(0,i-500), i+700));\n }\n}\n",
