    content: "const fs=require('fs');const path=require('path');\nconst terms=['新增银行存款账户','绑定银企互联','账户名称','银行卡号','请选择银行','请选择会计科目'];\nfunction walk(d){for(const n of fs.readdirSync(d)){if(['node_modules','.git','.turbo','webapp','dist'].includes(n))continue;const p=path.join(d,n);let st;try{st=fs.statSync(p)}catch(e){continue} if(st.isDirectory())walk(p); else if(/\\.(vue|ts|js|tsx|jsx|json|md)$/.test(n)){let t='';try{t=fs.readFileSync(p,'utf8')}catch(e){} if(terms.some(k=>t.includes(k))) console.log(p)}}}\nwalk('apps/web-ele/src');walk('skills');\n",
