    content: "const fs=require('fs');\nconst path=require('path');\nconst roots=['apps','packages','skills'];\nconst skip=new Set(['node_modules','.git','.pnpm-store','.turbo','dist','build']);\nfunction walk(d){\n  if(!fs.existsSync(d)) return;\n  for(const n of fs.readdirSync(d)){\n    const p=path.join(d,n);\n    let st; try{st=fs.statSync(p)}catch{continue}\n    if(st.isDirectory()){\n      if(skip.has(n)) continue;\n      if(n.toLowerCase().includes('ledger')) console.log(p);\n      walk(p);\n    } else {\n      const low=n.toLowerCase();\n      if(low.includes('breakdown') || low.includes('ledger')) console.log(p);\n    }\n  }\n}\nroots.forEach(r=>walk(path.join(process.cwd(), r)));\n",
