    path: "tmp_find_term.cjs",
    content: "const fs=require('fs');const path=require('path');const root=path.join(__dirname,'apps/web-ele/src');const term=process.argv[2]||'';function walk(d){for(const n of fs.readdirSync(d)){const p=path.join(d,n);const st=fs.statSync(p);if(st.isDirectory()){if(['node_modules','.git','.turbo','dist'].includes(n))continue;walk(p)}else if(['.ts','.tsx','.vue','.js'].includes(path.extname(n))){let t='';try{t=fs.readFileSync(p,'utf8')}catch{}if(t.includes(term))console.log(path.relative(__dirname,p).replace(/\\\\/g,'/'))}}}walk(root);",
