    path: "tmp_find_voucher_page_flow.cjs",
    content: "const fs=require('fs'),path=require('path');\nfunction walk(d){\n for(const n of fs.readdirSync(d)){\n  const p=path.join(d,n); const st=fs.statSync(p);\n  if(st.isDirectory()){ if(!['node_modules','.git','.turbo','dist'].includes(n)) walk(p); }\n  else if(/\\.(vue|ts)$/.test(n)){\n   const s=fs.readFileSync(p,'utf8');\n   if(s.includes('FinanceVoucherCreate')||s.includes('finance_voucher_create_draft')||s.includes('returnPath')) console.log(p);\n  }\n }\n}\nwalk('apps/web-ele/src');\n",
