    content: "const fs=require('fs');\nconst p='apps/web-ele/src/views/finance/assets/manage/list/index.vue';\nlet s=fs.readFileSync(p,'utf8');\ns=s.replace(/type AssetChangeVoucherDraft = \\{[\\s\\S]*?\\n\\};/, `type AssetChangeVoucherDraft = {\n  attachmentsCount?: number;\n  date?: number;\n  entries?: Array<Record<string, any>>;\n  note?: string;\n  returnPath?: string;\n  rowIds?: string[];\n  source?: 'asset-change';\n  voucherWord?: string;\n};`);\n// remove markRaw import if unused\ns=s.replace(/\\n  markRaw,/, '');\nfs.writeFileSync(p,s,'utf8');\n",
