    content: "const fs=require('fs');\nconst p='apps/web-ele/src/views/finance/settings/auxiliary/index.vue';\nlet s=fs.readFileSync(p,'utf8');\ns=s.replace(`onMounted(async () => {\\n  await loadDynamicTabs();`, `onMounted(async () => {\\n  if (typeof window !== 'undefined') {\\n    filterCollapsed.value = window.matchMedia('(max-width: 768px)').matches;\\n  }\\n  await loadDynamicTabs();`);\nfs.writeFileSync(p,s);\nconsole.log('fixed collapsed init');\n",
