    content: "const fs=require('fs');\nconst p='apps/web-ele/src/views/finance/assets/check-ledger/modules/form.vue';\nlet s=fs.readFileSync(p,'utf8');\nconst old=`    <template #footer>\\n      <ElButton @click=\"showDialog = false\">取消</ElButton>\\n      <ElButton type=\"primary\" @click=\"onSave\">保存</ElButton>\\n    </template>\\n  </div>`;\nconst neu=`    <div class=\"asset-change-inline-form__footer\">\\n      <ElButton @click=\"showDialog = false\">取消</ElButton>\\n      <ElButton type=\"primary\" @click=\"onSave\">保存</ElButton>\\n    </div>\\n  </div>`;\nif(!s.includes(old)) throw new Error('inline footer pattern not found');\ns=s.replace(old,neu);\ns=s.replace(`  font-weight: 600;\\n}\\n</style>`, `  font-weight: 600;\\n}\\n\\n.asset-change-inline-form__footer {\\n  display: flex;\\n  justify-content: flex-end;\\n  gap: 8px;\\n  padding: 0 0 12px;\\n}\\n</style>`);\nfs.writeFileSync(p,s,'utf8');\n",
