    path: "tmp_list_project_dept_files.cjs",
    content: "const fs=require('fs');const path=require('path');\nfunction walk(d,r=[]){for(const n of fs.readdirSync(d)){const p=path.join(d,n),st=fs.statSync(p);if(st.isDirectory()&&!['node_modules','.git','dist'].includes(n))walk(p,r);else if(/\\.(ts|vue)$/.test(n))r.push(p)}return r}\nconst out=[];\nfor(const d of ['apps/web-ele/src/api/erp','apps/web-ele/src/views/finance']){\n for(const f of walk(d)){const s=fs.readFileSync(f,'utf8');if(/department|dept|项目|部门|getAllSubjectList|project_id/i.test(s))out.push(f)}\n}\nconsole.log(out.slice(0,120).join('\\n'));\n",
