function listTmpScripts() {
  return TMP_SOURCES.map((item, index) => ({ index: index + 1, path: item.path, bytes: Buffer.byteLength(item.content, 'utf8') }));
}

function extractTmpScripts(targetDir = 'tmp_misc_extracted') {
  const fs = require('fs');
  const path = require('path');
  for (const item of TMP_SOURCES) {
    const file = path.join(targetDir, item.path);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, item.content, 'utf8');
  }
  return TMP_SOURCES.length;
}

if (require.main === module) {
  const cmd = process.argv[2] || 'list';
  if (cmd === 'extract') {
    const count = extractTmpScripts(process.argv[3] || 'tmp_misc_extracted');
    console.log(`extracted ${count} tmp scripts`);
  } else {
    console.log(JSON.stringify({ count: TMP_SOURCES.length, scripts: listTmpScripts() }, null, 2));
  }
}

module.exports = { TMP_SOURCES, listTmpScripts, extractTmpScripts };
